const NO_MOTION_LIMIT = 60 * 60;         // 1 hour
const NO_MOTION_LUEFTEN = 12 * 60 * 60;  // 12 hours

const CO2_OFF = 1800;
const CO2_ON_TREND = 2000;
const CO2_ON_ALWAYS = 2000;

// ------------------------------------------------
// Trend validation (Netatmo only)
// ------------------------------------------------
let co2Trend = "unknown";

if (
    co2Source === "netatmo" &&
    (rawTrend === "up" || rawTrend === "down" || rawTrend === "stable")
) {
    co2Trend = rawTrend;
}

// ------------------------------------------------
