// ------------------------------------------------

// ------------------------------------------------
// SAFETY OVERRIDE: very high CO2 always wins
// ------------------------------------------------
if (co2 >= CO2_ON_ALWAYS) {

    if (!ventilatorOn) {
        flow.set("bayernluft_on", true);
        msg.payload = {
            on: true,
            reason: "co2_critical",
            co2_source: co2Source
        };
        return msg;
    }

    return null;
}

// ------------------------------------------------
// Scheduled "Lüften" after 12h no motion
// Only between 12:00–12:59 and 08:00–08:59 Zurich time
// ------------------------------------------------
const inLueftenWindow = (zurichHour === 12 || zurichHour === 8);

if (
    sinceMotion > NO_MOTION_LUEFTEN &&
    inLueftenWindow &&
    co2 < CO2_ON_ALWAYS
) {
    if (!ventilatorOn) {
        flow.set("bayernluft_on", true);
        msg.payload = {
            on: true,
            reason: "scheduled_lueften",
            co2_source: co2Source
        };
        return msg;
    }

    return null;
}

// ------------------------------------------------
// No presence (>1h) → allow OFF (but not safety)
// ------------------------------------------------
if (sinceMotion > NO_MOTION_LIMIT) {

    if (ventilatorOn && co2 < CO2_ON_ALWAYS) {
        flow.set("bayernluft_on", false);
        msg.payload = {
            on: false,
            reason: "no_presence",
            co2_source: co2Source
        };
        return msg;
    }

    return null;
}

// ------------------------------------------------
// Normal presence-based control
// ------------------------------------------------

// OFF below lower threshold
if (co2 < CO2_OFF && ventilatorOn) {
    flow.set("bayernluft_on", false);
    msg.payload = {
        on: false,
        reason: "co2_low",
        co2_source: co2Source
    };
    return msg;
}

// Trend-based ON (Netatmo only)
if (
    !ventilatorOn &&
    co2 >= CO2_ON_TREND &&
    co2 < CO2_ON_ALWAYS &&
    co2Trend === "up"
) {
    flow.set("bayernluft_on", true);
    msg.payload = {
        on: true,
        reason: "co2_rising",
        co2_source: co2Source
    };
    return msg;
}

// ------------------------------------------------
// No state change
// ------------------------------------------------
return {};

