// ------------------------------------------------
const OFF_DELAY = 15 * 60;

const MIN_BRIGHTNESS = 20;
const MAX_BRIGHTNESS = 70;

// ------------------------------------------------
// Brightness calculation
// ------------------------------------------------
let desiredBrightness;

if (lux < 100) {
    desiredBrightness = 20;
}
else if (lux < 150) {
    desiredBrightness = 30;
}
else {
    const minLux = 150;
    const maxLux = 1000;
    const ratio = (lux - minLux) / (maxLux - minLux);
    desiredBrightness = 30 + ratio * (MAX_BRIGHTNESS - 30);
}

desiredBrightness = Math.round(
    Math.max(MIN_BRIGHTNESS, Math.min(MAX_BRIGHTNESS, desiredBrightness))
);

// ------------------------------------------------
// LOGIC
// ------------------------------------------------

// Motion → ensure ON and correct brightness
if (motion) {

    if (
        dimmerSource !== "input" &&
        (!dimmerOn || dimmerBrightness !== desiredBrightness)
    ) {
        flow.set("stairs_on", true);
        flow.set("stairs_brightness", desiredBrightness);
        flow.set("stairs_source", "auto");

        msg.payload = {
            on: true,
            brightness: desiredBrightness
        };
        return msg;
    }

    return null;
}

// No motion → timeout OFF
if (
    sinceMotion > OFF_DELAY &&
    dimmerOn &&
    dimmerSource !== "input"
) {
    flow.set("stairs_on", false);
    flow.set("stairs_source", "auto");

    msg.payload = { on: false };
    return msg;
}

// No state change
return {};

