else if (tempOutdoor < tempIndoor) {

    if (motion && tempIndoor < COMFORT_TEMP) {
        tempRequestsHeating = true;
        isComfortHeating = true;
    }

    if (tempIndoor >= COMFORT_TEMP) {
        tempRequestsHeating = false;
    }
}
else {
    tempRequestsHeating = false;
}

