    // Daytime hysteresis
    if (heatingOn) {
        if (batterySoc >= (BATTERY_FULL - BATT_HYST)) {
            batteryAllows = true;
        }
    } else {
        if (batterySoc >= BATTERY_FULL) {
            batteryAllows = true;
        }
    }

