// Retrieve previous value
let previous = flow.get("grid_power");

// Helper: trend detection
function getTrend(current, previous, threshold) {
    if (!Number.isFinite(previous)) return "stable";
    if (current - previous > threshold) return "up";
    if (previous - current > threshold) return "down";
    return "stable";
}

// Compute trend (threshold 50W to ignore noise)
let trend = getTrend(power, previous, 50);

// Store values
flow.set("grid_power", power);
flow.set("grid_power_trend", trend);
flow.set("grid_power_last_update", Date.now());

return msg;

// ------------------------------------------------
// FULL FLOW STATE SNAPSHOT LOGGER (EXTENDED)
// Trigger manually via Inject button
// ------------------------------------------------

function get(name, fallback = null) {
    let v = flow.get(name);
    return (v === undefined) ? fallback : v;
}

let nowMs = Date.now();
let nowSec = Math.floor(nowMs / 1000);

let snapshot = {

    timestamp_iso: new Date(nowMs).toISOString(),
    timestamp_unix: nowSec,

    // -------------------------
    // Heating
    // -------------------------
    heating_on: get("heating_on", false),

    // -------------------------
    // Primary Climate (Netatmo)
    // -------------------------
    netatmo_last_update: get("netatmo_last_update"),

    temperature_indoor: get("temperature_indoor"),
    temperature_indoor_trend: get("temperature_indoor_trend"),

    temperature_outdoor: get("temperature_outdoor"),
    temperature_outdoor_trend: get("temperature_outdoor_trend"),

    humidity_indoor: get("humidity_indoor"),
    humidity_outdoor: get("humidity_outdoor"),

    co2_indoor: get("co2_indoor"),
    indoor_co2_trend: get("indoor_co2_trend"),

    // -------------------------
    // Sensirion Backup - Individual Sensors
    // -------------------------
    sensirion_temp_bottom: get("sensirion_temp_bottom"),
    sensirion_temp_bathroom: get("sensirion_temp_bathroom"),
    sensirion_temp_top: get("sensirion_temp_top"),

    sensirion_hum_bottom: get("sensirion_hum_bottom"),
    sensirion_hum_bathroom: get("sensirion_hum_bathroom"),
    sensirion_hum_top: get("sensirion_hum_top"),

    sensirion_co2_top: get("sensirion_co2_top"),

    // -------------------------
    // Sensirion Backup - Aggregated
    // -------------------------
    sensirion_temperature: get("sensirion_temperature"),
    sensirion_humidity: get("sensirion_humidity"),
    sensirion_co2: get("sensirion_co2"),
    sensirion_last_update: get("sensirion_last_update"),

    // -------------------------
    // Energy
    // -------------------------
    solar_power: get("solar_power", 0),
    solar_power_trend: get("solar_power_trend"),
    solar_power_last_update: get("solar_power_last_update"),

    grid_power: get("grid_power", 0),
    grid_power_trend: get("grid_power_trend"),
    grid_power_last_update: get("grid_power_last_update"),

    battery_soc: get("battery_soc", 0),

    // -------------------------
    // Water Tank / Consumption
    // -------------------------

    level_liter: get("level_liter"),
    level_percent: get("level_percent"),
    water_use_l: get("water_use_l"),
    level_last_update: get("level_last_update"),

    // -------------------------
    // Pump
    // -------------------------
    pump_state: get("pump_on"),
    temperature_tech: get("temperature_tech"),

    // -------------------------
    // Flood Kitchen
    // -------------------------

    leakage_kitchen: get("leakage_kitchen"),

    // -------------------------
    // Motion + Lux (Main)
    // -------------------------
    motion: get("motion", false),
    last_motion: get("last_motion"),
    lux: get("lux"),

    // -------------------------
    // Motion + Lux (Bad)
    // -------------------------
    motion_bad: get("motion_bad", false),
    last_motion_bad: get("last_motion_bad"),
    lux_bad: get("lux_bad")
};


// ------------------------------------------------
// Derived Diagnostics
// ------------------------------------------------

if (snapshot.last_motion) {
    snapshot.seconds_since_motion =
        nowSec - snapshot.last_motion;
}

if (snapshot.last_motion_bad) {
    snapshot.seconds_since_motion_bad =
        nowSec - snapshot.last_motion_bad;
}

if (snapshot.solar_power_last_update) {
    snapshot.seconds_since_solar_update =
        Math.floor((nowMs - snapshot.solar_power_last_update) / 1000);
}

if (snapshot.grid_power_last_update) {
    snapshot.seconds_since_grid_update =
        Math.floor((nowMs - snapshot.grid_power_last_update) / 1000);
}

if (snapshot.sensirion_last_update) {
    snapshot.seconds_since_sensirion_update =
        Math.floor((nowMs - snapshot.sensirion_last_update) / 1000);
}


// ------------------------------------------------
// Output
// ------------------------------------------------

msg.payload = snapshot;
return msg;

// ------------------------------------------------
// SENSIRION BACKUP STORAGE + MEAN AGGREGATION
// Connect ALL backup MQTT topics here
// ------------------------------------------------

// Validate payload
let value = Number(msg.payload);
if (!Number.isFinite(value)) {
    return null; // ignore null / NaN
}

let topic = msg.topic || "";

// ------------------------------------------------
// Store individual sensor values
// ------------------------------------------------

function store(key, val) {
    flow.set(key, val);
}

// Temperature sensors
if (topic === "energiemonitor/humi/bottom/temperature") {
    store("sensirion_temp_bottom", value);
}
else if (topic === "energiemonitor/humi/bathroom/temperature") {
    store("sensirion_temp_bathroom", value);
}
else if (topic === "energiemonitor/aiq/top/temperature") {
    store("sensirion_temp_top", value);
}

// Humidity sensors
else if (topic === "energiemonitor/humi/bottom/humidity") {
    store("sensirion_hum_bottom", value);
}
else if (topic === "energiemonitor/humi/bathroom/humidity") {
    store("sensirion_hum_bathroom", value);
}
else if (topic === "energiemonitor/aiq/top/humidity") {
    store("sensirion_hum_top", value);
}

// CO2 sensor
else if (topic === "energiemonitor/co2/top/co2") {
    store("sensirion_co2_top", value);
}

else {
    return null; // ignore unrelated topics
}


// ------------------------------------------------
// Helper: calculate mean of valid numbers
// ------------------------------------------------

function mean(values) {
    let valid = values.filter(v => Number.isFinite(v));
    if (valid.length === 0) return null;
    return valid.reduce((a, b) => a + b, 0) / valid.length;
}


// ------------------------------------------------
// Calculate aggregated backup values
// ------------------------------------------------

// Temperature mean (3 sensors max)
let tempMean = mean([
    flow.get("sensirion_temp_bottom"),
    flow.get("sensirion_temp_bathroom"),
    flow.get("sensirion_temp_top")
]);

// Humidity mean (3 sensors max)
let humMean = mean([
    flow.get("sensirion_hum_bottom"),
    flow.get("sensirion_hum_bathroom"),
    flow.get("sensirion_hum_top")
]);

// CO2 mean (currently 1 sensor, future-proofed)
let co2Mean = mean([
    flow.get("sensirion_co2_top")
]);


// ------------------------------------------------
// Store aggregated backup values
// ------------------------------------------------

if (tempMean !== null)
    flow.set("sensirion_temperature", tempMean);

if (humMean !== null)
    flow.set("sensirion_humidity", humMean);

if (co2Mean !== null)
    flow.set("sensirion_co2", co2Mean);


// Optional: store last update timestamp
flow.set("sensirion_last_update", Date.now());


// No output needed (pure storage node)
return null;

// Ensure payload exists and contains a numeric value
if (msg.payload && typeof msg.payload.value === "number") {

    const soc = msg.payload.value;

    // Store SOC in flow context
    flow.set("battery_soc", soc);

    // Optional: also attach to msg for downstream debugging
    msg.battery_soc = soc;

    return msg;
}

// If invalid message, do nothing
return null;

// -------------------------
// 1. Store pump state & temperature
// -------------------------

let currentPumpState = flow.get("pump_on");

if (msg.payload) {
    // Pump state
    let pumpState = msg.payload?.switch0?.output;
    if (typeof pumpState !== "undefined") {
        flow.set("pump_on", pumpState);
        currentPumpState = pumpState;
    }

    // Temperature (correct path)
    let tempTech = msg.payload?.switch0?.temperature?.tC;
    if (typeof tempTech !== "undefined") {
        flow.set("temperature_tech", tempTech);
    }
}


// -------------------------
// 2. Check motion timeout (24h)
// -------------------------

let lastMotion = flow.get("last_motion");
let now = Math.floor(Date.now() / 1000);

if (!lastMotion) {
    lastMotion = now;
}

let secondsSinceMotion = now - lastMotion;
flow.set("seconds_since_motion", secondsSinceMotion);

let noMotionTooLong = secondsSinceMotion > 86400;


// -------------------------
// 3. Only send command if REALLY needed
// -------------------------

if (noMotionTooLong && currentPumpState === true) {

    flow.set("pump_on", false);

    return {
        payload: {
            method: "Switch.Set",
            parameters: {
                id: 0,
                on: false
            }
        }
    };
}


// -------------------------
// 4. No action
// -------------------------

return null;

// Ensure payload and sensor object exist
if (msg.payload && msg.payload.sensor && typeof msg.payload.sensor.flood !== "undefined") {

    let newLeakState = msg.payload.sensor.flood; // true / false
    let currentLeakState = flow.get("leakage_kitchen");

    // Only update if state has changed
    if (currentLeakState !== newLeakState) {

        flow.set("leakage_kitchen", newLeakState);

        // Store timestamp (use device timestamp if available, else current time)
        let ts = msg.payload.sensor.timestamp || Math.floor(Date.now() / 1000);
        flow.set("leakage_kitchen_ts", ts);
    }
}

// Pass message through unchanged
return msg;

try {
    // Default: do nothing unless valid event
    if (
        msg.payload &&
        msg.payload.input_event &&
        typeof msg.payload.input_event.event === "string"
    ) {

        let event = msg.payload.input_event.event;      // S, SS, SSS, L
        let newCount = msg.payload.input_event.event_cnt;
        let lastCount = flow.get("button_last_event_cnt");

        // Only process new events
        if (newCount !== lastCount) {

            flow.set("button_last_event_cnt", newCount);

            // Determine timestamp
            let ts = (typeof msg.payload.ts === "number")
                ? msg.payload.ts
                : Math.floor(Date.now() / 1000);

            // Map event → variable
            switch (event) {
                case "S":
                    flow.set("button_last_pressed_s", ts);
                    break;

                case "SS":
                    flow.set("button_last_pressed_ss", ts);
                    break;

                case "SSS":
                    flow.set("button_last_pressed_sss", ts);
                    break;

                case "L":
                    flow.set("button_last_pressed_l", ts);
                    break;

                default:
                    // Unknown event → ignore safely
                    break;
            }
        }
    } else {
        // Invalid payload → set all to null (fail-safe)
        flow.set("button_last_pressed_s", null);
        flow.set("button_last_pressed_ss", null);
        flow.set("button_last_pressed_sss", null);
        flow.set("button_last_pressed_l", null);
    }

} catch (err) {
    // Hard failure → reset all
    flow.set("button_last_pressed_s", null);
    flow.set("button_last_pressed_ss", null);
    flow.set("button_last_pressed_sss", null);
    flow.set("button_last_pressed_l", null);
}

// Pass message through
return msg;

const c = msg.payload.components;

// Sensor values
const rawDistance = c.Tof_NoHist_Distance.value;
const tofStatus = c.TOF_Status?.value;
const battery = c.Battery_Voltage?.value;
const temperature = c.Temperature?.value;

const timestamp = msg.payload.baseStations?.[0]?.rxTime || null;

const bs = msg.payload.baseStations?.[0] || {};
const rssi = bs.rssi;
const snr = bs.snr;

const validMeasurement =
    tofStatus === 0 &&
    rawDistance > 0 &&
    rawDistance < 4000;

// --- Deadband filter (3 mm) ---
const DEADBAND_MM = 3;
let lastAccepted = context.get('lastAcceptedDistance');
let distance;

if (!validMeasurement) {
    distance = lastAccepted ?? null;
} else if (lastAccepted === undefined || Math.abs(rawDistance - lastAccepted) >= DEADBAND_MM) {
    context.set('lastAcceptedDistance', rawDistance);
    distance = rawDistance;
} else {
    distance = lastAccepted; // suppress small fluctuation
}
// --- End deadband filter ---

let liters = null;
let fillPercent = null;

if (validMeasurement && distance !== null) {
    const FULL_DISTANCE = 270;
    const EMPTY_DISTANCE = 1000;
    const MAX_LITERS = 2000;

    liters = ((EMPTY_DISTANCE - distance) / (EMPTY_DISTANCE - FULL_DISTANCE)) * MAX_LITERS;
    liters = Math.max(0, Math.min(MAX_LITERS, liters));
    fillPercent = Math.round((liters / MAX_LITERS) * 100);
    liters = Math.round(liters);
}

msg.payload = {
    valid: validMeasurement,
    timestamp,
    distance_mm: validMeasurement ? distance : null,
    distance_raw_mm: validMeasurement ? rawDistance : null,  // kept for diagnostics
    fill_liters: liters,
    fill_percent: fillPercent,
    tof_status: tofStatus,
    battery_v: battery,
    temperature_c: temperature,
    signal: {
        rssi,
        snr,
        quality:
            (snr > 10 && rssi > -100) ? "excellent" :
            (snr > 5  && rssi > -110) ? "good" :
            (snr > 0  && rssi > -120) ? "fair" :
            "poor"
    },
    uplink_counter: c.Uplink_Counter?.value
};

return msg;

if (!msg.payload?.valid) {
    return null;
}

const currentLevel = msg.payload.fill_liters;
const currentPercent = msg.payload.fill_percent;
const currentTimestamp = msg.payload.timestamp;
const tankTemperature = msg.payload.temperature_c;

// Previous values
const previousLevel = flow.get("level_liter");
let waterUse = flow.get("water_use_l") || 0;

// Compute delta only if previous exists
if (typeof previousLevel === "number") {

    const delta = previousLevel - currentLevel;

    // Only consumption (tank decreasing)
    if (delta > 0) {
        waterUse += delta;
    }
}

// Store state
flow.set("level_last_update", currentTimestamp);
flow.set("level_liter", currentLevel);
flow.set("level_percent", currentPercent);
flow.set("water_use_l", waterUse);
flow.set("tank_temperature", tankTemperature);

// OUTPUT (IMPORTANT: move into payload)
msg.payload = {
    level_last_update: currentTimestamp,
    level_liter: currentLevel,
    level_percent: currentPercent,
    water_use_l: waterUse,
    tank_temperature: tankTemperature
};

return msg;

// Build payload from flow context variables
const payload = {
    temperature_indoor: flow.get("temperature_indoor"),
    temperature_outdoor: flow.get("temperature_outdoor"),

    humidity_indoor: flow.get("humidity_indoor"),

    co2_indoor: flow.get("co2_indoor"),
    heating_on: flow.get("heating_on"),
    solar_power: Math.floor(Number(flow.get("solar_power"))),

    battery_soc: flow.get("battery_soc"),
    level_liter: flow.get("level_liter"),
    level_percent: flow.get("level_percent"),
    tank_temperature: flow.get("tank_temperature")
};

// Remove undefined/null values
Object.keys(payload).forEach(key => {
    if (payload[key] === undefined || payload[key] === null) {
        delete payload[key];
    }
});

// --- Zurich timestamp ---
const now = new Date();
const tz = "Europe/Zurich";

// hour + minute (Zurich time)
const timeParts = new Intl.DateTimeFormat("en-GB", {
    timeZone: tz,
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
}).format(now).split(":");

const hour = parseInt(timeParts[0], 10);
const minute = parseInt(timeParts[1], 10);

// Day + month number
const parts = new Intl.DateTimeFormat("de-CH", {
    timeZone: tz,
    weekday: "short",
    day: "2-digit",
    month: "2-digit"
}).formatToParts(now);

const weekday = parts.find(p => p.type === "weekday").value;
const day = parts.find(p => p.type === "day").value;
const monthNum = parseInt(parts.find(p => p.type === "month").value, 10);

// Force 3-letter German month abbreviations
const months = ["Jan", "Feb", "Mär", "Apr", "Mai", "Jun", "Jul", "Aug", "Sep", "Okt", "Nov", "Dez"];
const month = months[monthNum - 1];

const date = `${weekday} ${day} ${month}`;

// Add timestamp block
payload.timestamp = {
    hour,
    minute,
    date
};

// Build MQTT message
msg.topic = "display";
msg.payload = payload;

return msg;

// Store state
flow.set("water_use_l", msg.payload);

return msg;
